/// Returns `true` if `n` is even (divisible by 2), `false` otherwise.
fn is_even_exec(n: u32) -> bool {
    n % 2 == 0
}

/// Returns `true` if and only if there exists at least one even number
/// in the array `arr`. Returns `false` on an empty array or if no
/// element is even.
fn is_product_even(arr: &Vec<u32>) -> bool {
    for &x in arr.iter() {
        if is_even_exec(x) {
            return true;
        }
    }
    false
}

